    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Strange Numbers Puzzle</title>
    <script>
        function solvePuzzle() {
            const table = document.getElementById('puzzleTable');
            const rows = table.rows;

            // Get the missing number cell
            const missingNumberCell = rows[2].cells[2];

            // Calculate the missing number
            let sum = 0;
            for (let i = 0; i < rows.length; i++) {
                const row = rows[i];
                for (let j = 0; j < row.cells.length; j++) {
                    const cell = row.cells[j];
                    sum += parseInt(cell.textContent);
                }
            }

            const missingNumber = sum - 9;
            missingNumberCell.textContent = missingNumber;
        }
    </script>
</head>
<body>
