            int totalCost = CalculateTotalCost(clothesPrice, bookPrice);

            if (carPrice < totalCost * 2)
            {
                carPrice = totalCost * 2;
            }

            int finalTotalCost = CalculateTotalCost(clothesPrice, bookPrice, carPrice);

            Console.WriteLine("Total Cost: " + finalTotalCost);
