Here's a simple React component using Hooks to convert between different temperature units:

```javascript
import React, { useState } from 'react';

function TemperatureConverter() {
  const [temperature, setTemperature] = useState(0);
  const [unit, setUnit] = useState('Celsius');

  const handleConvert = () => {
    if (unit === 'Celsius') {
      setTemperature((temperature * 9 / 5) + 32);
      setUnit('Fahrenheit');
    } else {
      setTemperature((temperature - 32) * 5 / 9);
      setUnit('Celsius');
    }
  };

  return (
    <div>
      <input type="number" value={temperature} onChange={e => setTemperature(parseFloat(e.target.value))} />
      <button onClick={handleConvert}>Convert</button>
      <p>Temperature in {unit}: {temperature}°{unit}</p>
    </div>
  );
}

export default TemperatureConverter;
```

