```go
package main

import (
	"fmt"
	"io/ioutil"
	"regexp"
	"strings"

	"github.com/apache/avro/avro"
	"github.com/apache/avro/avro/schema"
)

func main() {
	file := "example.go" // Replace with the name of your Go source file
	structName := "MyStruct" // Replace with the name of the struct you want to convert

	content, err := ioutil.ReadFile(file)
	if err != nil {
		fmt.Println("Error reading file:", err)
		return
	}

	re := regexp.MustCompile(`type\s+(\w+)\s+struct`)
	matches := re.FindStringSubmatch(string(content))
	if len(matches) != 2 {
		fmt.Println("Error parsing file:", "Unable to find struct definition")
		return
	}

	structType := matches[1]

	fields := []avro.Field{}
	for _, field := range strings.Split(strings.TrimSpace(string(content)), "\n") {
		if strings.HasPrefix(field, fmt.Sprintf("%s ", structType)) {
			parts := strings.SplitN(field, " ", 2)
			name := parts[0][len(structType):]
			typeStr := parts[1]

			fieldSchema, err := avro.ParseSchema(typeStr)
			if err != nil {
				fmt.Println("Error parsing schema for", name, ":", err)
				continue
			}

			fields = append(fields, avro.Field{Name: name, Schema: fieldSchema})
		}
	}

	schemaDef := &schema.Schema{
		Name: structName,
		Fields: fields,
	}

